$ErrorActionPreference='Stop';$utf8=[Text.UTF8Encoding]::new($false);$fixture=Join-Path ([IO.Path]::GetTempPath()) ('et-security-assessment-'+[guid]::NewGuid().ToString('N'));New-Item -ItemType Directory $fixture|Out-Null
try{$keys=@{};foreach($name in @('assessor','requester','approver','release')){$rsa=[Security.Cryptography.RSA]::Create(3072);try{$private=Join-Path $fixture "$name.private.pem";$public=Join-Path $fixture "$name.public.pem";[IO.File]::WriteAllText($private,$rsa.ExportPkcs8PrivateKeyPem(),$utf8);[IO.File]::WriteAllText($public,$rsa.ExportSubjectPublicKeyInfoPem(),$utf8);$keys[$name]=@{Private=$private;Public=$public}}finally{$rsa.Dispose()}}
    . "$PSScriptRoot/SecurityAssessment.Common.ps1";$evidence=@();foreach($type in $script:RequiredSecurityAssessmentTypes){$file=Join-Path $fixture "$type.json";[IO.File]::WriteAllText($file,([ordered]@{Passed=$true;RunId="$type-test"}|ConvertTo-Json),$utf8);$evidence+=[ordered]@{Type=$type;EvidenceFile=$file}}
    $evidenceFile=Join-Path $fixture 'evidence.json';$findingsFile=Join-Path $fixture 'findings.json';[IO.File]::WriteAllText($evidenceFile,($evidence|ConvertTo-Json -Depth 5),$utf8)
    $findings=@([ordered]@{FindingId='SEC-001';Severity='High';Status='Closed';ResolutionEvidence='fix-commit-and-retest'},[ordered]@{FindingId='SEC-002';Severity='Medium';Status='RiskAccepted';RiskAcceptanceReason='bounded test environment';RiskAcceptanceExpiresAtUtc=[DateTimeOffset]::UtcNow.AddDays(7).ToString('O')})
    [IO.File]::WriteAllText($findingsFile,($findings|ConvertTo-Json -Depth 5),$utf8)
    $p=@{AssessmentId='security-assessment-test';DeploymentId='deployment-test';ReleaseVersion='0.0.0-test';AssessmentEvidenceFile=$evidenceFile;FindingsFile=$findingsFile;ValidUntilUtc=[DateTimeOffset]::UtcNow.AddDays(1);AssessedBy='security-assessor';RequestedBy='release-requester';ApprovedBy='release-approver';AssessorPrivateKeyFile=$keys.assessor.Private;AssessorKeyId='assessor';RequesterPrivateKeyFile=$keys.requester.Private;RequesterKeyId='requester';ApproverPrivateKeyFile=$keys.approver.Private;ApproverKeyId='approver';ReleaseSigningPublicKeyFile=$keys.release.Public;OutputDirectory=(Join-Path $fixture 'reports');TestOnlyReport=$true}
    $created=(((& "$PSScriptRoot/New-ServerSecurityAssessment.ps1" @p)-join[Environment]::NewLine)|ConvertFrom-Json);$v=@{AssessmentFile=$created.AssessmentFile;AssessorPublicKeyFile=$keys.assessor.Public;ExpectedAssessorKeyId='assessor';RequesterPublicKeyFile=$keys.requester.Public;ExpectedRequesterKeyId='requester';ApproverPublicKeyFile=$keys.approver.Public;ExpectedApproverKeyId='approver';ReleaseSigningPublicKeyFile=$keys.release.Public;AllowTestReport=$true}
    & "$PSScriptRoot/Test-ServerSecurityAssessment.ps1" @v|Out-Null
    $prod=$v.Clone();$prod.Remove('AllowTestReport');$rejected=$false;try{& "$PSScriptRoot/Test-ServerSecurityAssessment.ps1" @prod|Out-Null}catch{$rejected=$true};if(-not$rejected){throw 'Test report was accepted for production'}
    [IO.File]::WriteAllText($findingsFile,(@([ordered]@{FindingId='SEC-003';Severity='Critical';Status='Open'})|ConvertTo-Json -Depth 5),$utf8);$bad=$p.Clone();$bad.AssessmentId='open-critical';$rejected=$false;try{& "$PSScriptRoot/New-ServerSecurityAssessment.ps1" @bad|Out-Null}catch{$rejected=$true};if(-not$rejected){throw 'Open critical finding was accepted'}
    [IO.File]::WriteAllText($findingsFile,($findings|ConvertTo-Json -Depth 5),$utf8);$missing=@($evidence|Where-Object Type -CNE 'PenetrationTest');[IO.File]::WriteAllText($evidenceFile,($missing|ConvertTo-Json -Depth 5),$utf8);$bad=$p.Clone();$bad.AssessmentId='missing-pentest';$rejected=$false;try{& "$PSScriptRoot/New-ServerSecurityAssessment.ps1" @bad|Out-Null}catch{$rejected=$true};if(-not$rejected){throw 'Missing penetration test was accepted'}
    $tamper=Join-Path $fixture 'PermissionAudit.json';[IO.File]::AppendAllText($tamper,' ');$rejected=$false;try{& "$PSScriptRoot/Test-ServerSecurityAssessment.ps1" @v|Out-Null}catch{$rejected=$true};if(-not$rejected){throw 'Tampered assessment evidence was accepted'}
    $bad=$p.Clone();$bad.AssessmentId='reused-role';$bad.ApproverPrivateKeyFile=$keys.requester.Private;$rejected=$false;try{& "$PSScriptRoot/New-ServerSecurityAssessment.ps1" @bad|Out-Null}catch{$rejected=$true};if(-not$rejected){throw 'Reused approval key was accepted'}
    [ordered]@{Passed=$true;RequiredAssessmentTypes=5;TripleSignaturesVerified=$true;TestOnlyProductionUseRejected=$true;OpenCriticalRejected=$true;MissingPenetrationTestRejected=$true;EvidenceTamperRejected=$true;RoleReuseRejected=$true}|ConvertTo-Json
}finally{$temp=[IO.Path]::GetFullPath([IO.Path]::GetTempPath()).TrimEnd('\','/')+[IO.Path]::DirectorySeparatorChar;$resolved=[IO.Path]::GetFullPath($fixture);if($resolved.StartsWith($temp,[StringComparison]::OrdinalIgnoreCase)-and[IO.Path]::GetFileName($resolved)-match'^et-security-assessment-[a-f0-9]{32}$'-and(Test-Path $resolved)){Remove-Item $resolved -Recurse -Force}}
